     } else {
       @stn.analyze(value)
     }
-    write_stdout(result.stringify() + "\n")
+    let output = if planning {
+      result.stringify()
+    } else {
+      numeric_output(result)
+    }
+    write_stdout(output + "\n")
   } catch {
     @stn.StnError(code, message) => {
       write_stderr(code + ": " + message + "\n")
@@ -56,3 +61,55 @@
     }
   }
 }
+
+///|
+fn numeric_output(result : Json) -> String {
+  let buf = StringBuilder()
+  write_numeric_value(buf, result)
+  buf.to_string()
+}
+
+///|
+// CLI results have a fixed maximum depth. Keep core JSON string escaping.
+fn write_numeric_value(buf : StringBuilder, value : Json) -> Unit {
+  match value {
+    Object(fields) => {
+      buf.write_char('{')
+      let mut first = true
+      for key, field_value in fields {
+        if !first {
+          buf.write_char(',')
+        }
+        first = false
+        write_quoted_result_string(buf, key)
+        buf.write_char(':')
+        write_numeric_value(buf, field_value)
+      }
+      buf.write_char('}')
+    }
+    Array(items) => {
+      buf.write_char('[')
+      for i, item in items {
+        if i > 0 {
+          buf.write_char(',')
+        }
+        write_numeric_value(buf, item)
+      }
+      buf.write_char(']')
+    }
+    String(text) => write_quoted_result_string(buf, text)
+    Number(number, repr~) =>
+      match repr {
+        None => buf.write_object(number)
+        Some(text) => buf.write_string(text)
+      }
+    Null => buf.write_string("null")
+    True => buf.write_string("true")
+    False => buf.write_string("false")
+  }
+}
+
+///|
+fn write_quoted_result_string(buf : StringBuilder, text : String) -> Unit {
+  buf.write_string(Json::string(text).stringify())
+}

